import{c as a,Q as t,j as s,m as i}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Self-Evolving Agent Harnesses via Gated Semantic Quality-Diversity","description":"","frontmatter":{"url":"https://arxiv.org/abs/2607.13683","title":"Self-Evolving Agent Harnesses via Gated Semantic Quality-Diversity","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2607.13683,"authors":["Xiaotian Luo","Fengxingyu Wang","Chuanrui Hu","Dizhan Xue","Yafeng Deng"],"pdf_path":"pdfs/2607.13683.pdf","published_date":"2026-07-15T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-07-15-self-evolving-agent-harnesses-gated-quality-diversity-2607-13683.md","filePath":"research/papers/2026-07-15-self-evolving-agent-harnesses-gated-quality-diversity-2607-13683.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-07-15-self-evolving-agent-harnesses-gated-quality-diversity-2607-13683.md"};function r(o,e,l,h,d,g){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="self-evolving-agent-harnesses-via-gated-semantic-quality-diversity" tabindex="-1">Self-Evolving Agent Harnesses via Gated Semantic Quality-Diversity <a class="header-anchor" href="#self-evolving-agent-harnesses-via-gated-semantic-quality-diversity" aria-label="Permalink to &quot;Self-Evolving Agent Harnesses via Gated Semantic Quality-Diversity&quot;">​</a></h1><p><strong>Authors</strong>: Xiaotian Luo, Fengxingyu Wang, Chuanrui Hu, Dizhan Xue, Yafeng Deng <strong>Published</strong>: July 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2607.13683" target="_blank" rel="noreferrer">https://arxiv.org/abs/2607.13683</a><strong>arXiv ID</strong>: 2607.13683 <strong>Categories</strong>: Computer Science &gt; Computation and Language (cs.CL) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2607.13683" target="_blank" rel="noreferrer">research/papers/pdfs/2607.13683.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>An LLM agent&#39;s real-task performance is shaped as much by the harness around its model as by the frozen model itself: its prompts, injected knowledge, runtime control, and configuration. In deployment the harness is often the only lever available, so improving it automatically is the natural way to raise performance without touching the weights. The hard part is not generating changes but knowing which one truly helped. Self-generated feedback is noisy, and an apparent gain can be a measurement artifact or an edit that merely overfits the tasks it was tuned on. We present a self-evolving agent-harness framework that separates proposing changes from crediting them: a language model diagnoses failures and proposes patches, while all sampling, measurement, and significance testing are owned by deterministic code, so every credited improvement is trustworthy by construction. Patches populate a gated, categorical quality-diversity archive (GSME) keyed on the (WHERE x WHY) pathology an edit addresses rather than the tasks it fixes, an anti-overfitting inductive bias; generalization is measured on a sealed test scored only after evolution. Across seven domains with a frozen open-weight model, the harness is train-selected and scored once on a sealed test; its credited gains there are +9 to +15.5pp and retain 86-147% of the training gain, evidence they generalize rather than overfit. The winning patch tracks the model&#39;s dominant pathology, not its size or family: changing the model can change the pathology and the patch, while the same pathology-to-patch match recurs across two model families. What transfers is the diagnose-and-credit loop, not any specific harness.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>核心設計：把「提出變更」（LLM 判斷）與「認證變更」（確定性程式碼做取樣/測量/顯著性檢定）嚴格分離——LLM 只診斷失敗並提案 patch，是否真的有效由機械統計驗證，避免自報成功的測量假象。</li><li>用 gated categorical quality-diversity archive（GSME）以「(WHERE x WHY) 病理類型」而非「修了哪些任務」為 key，作為抗過擬合的歸納偏誤；泛化能力只在演化結束後於 sealed test 評一次分。</li><li>七個 domain 上實測：credited gain +9~15.5pp，且保留 86–147% 的訓練期增益，證明是真泛化而非過擬合；勝出的 patch 追蹤模型的主要病理類型而非模型大小/家族——換模型會換病理與 patch，但「診斷→認證」迴圈本身可遷移。</li><li><strong>Workspace 關聯</strong>：與 core.md 公理「判斷 vs 決定」幾乎逐字對應（LLM 判斷、確定性程式碼決定）；sealed-test-after-evolution 的做法直接印證同批次 2607.12227 對 harness evolution 評測方法論的批評，是該問題的一個正面解法範例，可供 <code>/autoload-evolution</code> 或 <code>harness-meta:self-audit</code> 未來設計「驗證後才記入」機制參考。</li></ul>',8)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
